CREATE TABLE app_users (id uuid primary key,email varchar(320) unique not null,password_hash varchar(100) not null,enabled boolean not null default true);
CREATE TABLE user_roles (user_id uuid references app_users(id) on delete cascade,role varchar(30) not null,primary key(user_id,role));
CREATE TABLE refresh_tokens (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,token_hash varchar(64) unique not null,expires_at timestamptz not null,revoked boolean not null default false);
CREATE TABLE fitness_profile (id uuid primary key,user_id uuid unique not null references app_users(id) on delete cascade,display_name varchar(120),goal varchar(80),fitness_level varchar(30),equipment varchar(120),limitations text,activity_target int,weekly_minutes int,sleep_target_hours numeric,step_target int,calorie_target int,protein_target_g int,water_target_oz int,target_weight_lb numeric,created_at timestamptz default now(),updated_at timestamptz default now());
CREATE TABLE daily_metrics (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,metric_date date not null,steps int,sleep_hours numeric,calories_burned int,water_oz int,resting_heart_rate int,readiness int,hrv int,active_minutes int,stress_level int,unique(user_id,metric_date));
CREATE TABLE body_metrics (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,metric_date date not null,weight_lb numeric,body_fat_pct numeric,waist_in numeric,chest_in numeric,arm_in numeric,thigh_in numeric,unique(user_id,metric_date));
CREATE TABLE exercises (id uuid primary key,name varchar(120) not null,description text,muscle_group varchar(40),secondary_muscles text,equipment varchar(80),difficulty varchar(30),instructions text,is_compound boolean default false);
CREATE TABLE foods (id uuid primary key,name varchar(160) not null,category varchar(60),serving_size numeric,serving_unit varchar(30),calories numeric,protein_g numeric,carbs_g numeric,fat_g numeric,fiber_g numeric,sugar_g numeric,sodium_mg numeric,source varchar(40));
CREATE TABLE workouts (id uuid primary key,user_id uuid references app_users(id) on delete cascade,title varchar(160),workout_type varchar(60),duration_minutes int,calories_burned int,intensity varchar(40),workout_date date,completed boolean,notes text,perceived_effort int,distance_miles numeric);
CREATE TABLE workout_sessions (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,title varchar(160),workout_type varchar(60),started_at timestamptz,completed_at timestamptz,duration_minutes int,notes text,perceived_effort int,completed boolean,created_at timestamptz default now());
CREATE TABLE workout_exercises (id uuid primary key,workout_session_id uuid not null references workout_sessions(id) on delete cascade,exercise_id uuid not null references exercises(id),order_index int,notes text);
CREATE TABLE exercise_sets (id uuid primary key,workout_exercise_id uuid not null references workout_exercises(id) on delete cascade,set_number int,reps int,weight numeric,weight_unit varchar(10) default 'lb',duration_seconds int,distance numeric,distance_unit varchar(10),rpe numeric,completed boolean);
CREATE TABLE workout_templates (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,name varchar(160),description text,workout_type varchar(60),estimated_minutes int,is_favorite boolean default false);
CREATE TABLE workout_template_exercises (id uuid primary key,template_id uuid not null references workout_templates(id) on delete cascade,exercise_id uuid not null references exercises(id),order_index int,target_sets int,target_reps varchar(40),target_weight numeric);
CREATE TABLE plan_sessions (id uuid primary key,user_id uuid references app_users(id) on delete cascade,day_index int,title varchar(160),workout_type varchar(60),intensity varchar(40),duration_minutes int,completed boolean);
CREATE TABLE personal_records (id uuid primary key,user_id uuid references app_users(id) on delete cascade,exercise varchar(120),record_value numeric,unit varchar(20),achieved_date date,previous_value numeric,created_at timestamptz default now());

CREATE TABLE meals (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,meal_date date,meal_type varchar(30),name varchar(200),source varchar(30),calories numeric,protein_g numeric,carbs_g numeric,fat_g numeric,fiber_g numeric,created_at timestamptz default now());
CREATE TABLE meal_items (id uuid primary key,meal_id uuid not null references meals(id) on delete cascade,food_id uuid references foods(id),food_name varchar(160),quantity numeric,grams numeric,calories numeric,protein_g numeric,carbs_g numeric,fat_g numeric,fiber_g numeric,source varchar(30));
CREATE TABLE food_scans (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,meal_id uuid references meals(id),status varchar(20),model varchar(80),image_path text,error text,created_at timestamptz default now());
CREATE TABLE food_scan_items (id uuid primary key,scan_id uuid not null references food_scans(id) on delete cascade,food_id uuid references foods(id),food_name varchar(160),estimated_grams numeric,confirmed_grams numeric,confidence numeric,calories numeric,protein_g numeric,carbs_g numeric,fat_g numeric,fiber_g numeric,sugar_g numeric,sodium_mg numeric,user_edited boolean default false);
CREATE TABLE ai_usage (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,feature varchar(40),model varchar(80),input_tokens int,output_tokens int,success boolean,estimated_cost numeric,created_at timestamptz default now());
CREATE TABLE habits (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,name varchar(120),description text,icon varchar(40),target_per_week int,color varchar(20),active boolean default true);
CREATE TABLE habit_logs (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,habit_id uuid not null references habits(id) on delete cascade,log_date date,completed boolean,unique(habit_id,log_date));
CREATE TABLE goals (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,goal_type varchar(50),title varchar(160),description text,start_value numeric,target_value numeric,current_value numeric,unit varchar(20),start_date date,target_date date,status varchar(30),created_at timestamptz default now());
CREATE TABLE reminders (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,type varchar(40),title varchar(160),message text,scheduled_time time,days_of_week text,enabled boolean,quiet_hours_start time,quiet_hours_end time);
CREATE TABLE health_devices (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,device_name varchar(120),device_type varchar(60),status varchar(30),last_sync timestamptz,created_at timestamptz default now());
CREATE TABLE coach_notifications (id uuid primary key,user_id uuid not null references app_users(id) on delete cascade,title varchar(160),message text,kind varchar(20),is_read boolean default false,created_at timestamptz default now());
